function securityHeaders(res){
 res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('X-Frame-Options','DENY');res.setHeader('Referrer-Policy','strict-origin-when-cross-origin');res.setHeader('Permissions-Policy','camera=(self), microphone=(), geolocation=()');
 res.setHeader('Cross-Origin-Opener-Policy','same-origin');
 res.setHeader('Content-Security-Policy',"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: blob: https://images.unsplash.com; media-src 'self' blob:; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'; form-action 'self'");
 if(process.env.NODE_ENV==='production')res.setHeader('Strict-Transport-Security','max-age=31536000; includeSubDomains');
}
function json(res,status,payload){const out=JSON.stringify(payload);securityHeaders(res);res.writeHead(status,{'Content-Type':'application/json; charset=utf-8','Content-Length':Buffer.byteLength(out),'Cache-Control':'no-store'});res.end(out)}
const ok=(res,data=null,status=200)=>{json(res,status,{success:true,data});if(status<400&&res._fsMutation)queueMicrotask(()=>{try{emitMutationSync(res._fsMutation,data,status)}catch(e){console.error('realtime mutation',e.message)}})};
const fail=(res,status,message,code='ERROR',details=null)=>json(res,status,{success:false,message,code,...(details?{details}:{})});
const safe=(v,max=1200)=>String(v??'').trim().slice(0,max);
function parseCookies(req){const out={};for(const part of String(req.headers.cookie||'').split(';')){const i=part.indexOf('=');if(i>0)out[part.slice(0,i).trim()]=decodeURIComponent(part.slice(i+1).trim())}return out}
async function body(req,limit=52*1024*1024){return new Promise((resolve,reject)=>{let size=0;const chunks=[];req.on('data',c=>{size+=c.length;if(size>limit){reject(Object.assign(new Error('Request is too large.'),{status:413}));req.destroy();return}chunks.push(c)});req.on('end',()=>{if(!chunks.length)return resolve({});try{resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')))}catch{reject(Object.assign(new Error('Invalid request body.'),{status:400}))}});req.on('error',reject)})}
async function rawBody(req,limit=20*1024*1024){return new Promise((resolve,reject)=>{let size=0;const chunks=[];req.on('data',c=>{size+=c.length;if(size>limit){reject(Object.assign(new Error('Upload is too large.'),{status:413}));req.destroy();return}chunks.push(c)});req.on('end',()=>resolve(Buffer.concat(chunks)));req.on('error',reject)})}
function setCookie(res,name,value,maxAge=1209600){const secure=process.env.NODE_ENV==='production'?'; Secure':'';res.setHeader('Set-Cookie',`${name}=${encodeURIComponent(value)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${maxAge}${secure}`)}
function clearCookie(res,name){res.setHeader('Set-Cookie',`${name}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0`)}
function guestId(req,res){let id=parseCookies(req).fs_guest;if(!/^[a-f0-9]{32}$/.test(id||'')){id=crypto.randomBytes(16).toString('hex');setCookie(res,'fs_guest',id,86400)}return id}
function claimGuest(req,userId){const id=parseCookies(req).fs_guest;if(id&&/^[a-f0-9]{32}$/.test(id))db.prepare('UPDATE scans SET user_id=?,guest_id=NULL WHERE guest_id=? AND user_id IS NULL').run(userId,id)}
function rateLimit(req,res,key='api',max=180,windowMs=60000){const forwarded=process.env.FOODSNAP_TRUST_PROXY==='1'?String(req.headers['x-forwarded-for']||'').split(',')[0].trim():'';const ip=forwarded||req.socket.remoteAddress||'local',t=Date.now(),start=Math.floor(t/windowMs)*windowMs,k=`${key}:${ip}:${start}`,expires=start+windowMs*2;try{db.prepare(`INSERT INTO rate_limit_buckets(bucket_key,window_start,count,expires_at) VALUES(?,?,1,?) ON CONFLICT(bucket_key) DO UPDATE SET count=count+1`).run(k,start,expires);const count=db.prepare('SELECT count FROM rate_limit_buckets WHERE bucket_key=?').get(k)?.count||1;if(Math.random()<0.01)db.prepare('DELETE FROM rate_limit_buckets WHERE expires_at<?').run(t);if(count>max){res.setHeader('Retry-After',String(Math.max(1,Math.ceil((start+windowMs-t)/1000))));fail(res,429,'Too many requests. Please wait a moment and try again.','RATE_LIMIT');return false}return true}catch{return true}}
function clientIp(req){const forwarded=process.env.FOODSNAP_TRUST_PROXY==='1'?String(req.headers?.['x-forwarded-for']||'').split(',')[0].trim():'';return forwarded||req.socket?.remoteAddress||'local'}
function deviceName(ua=''){ua=String(ua||'');const browser=/Edg\//.test(ua)?'Edge':/OPR\//.test(ua)?'Opera':/Chrome\//.test(ua)?'Chrome':/Firefox\//.test(ua)?'Firefox':/Safari\//.test(ua)?'Safari':'Browser',os=/Windows/.test(ua)?'Windows':/Android/.test(ua)?'Android':/iPhone|iPad/.test(ua)?'iOS':/Mac OS/.test(ua)?'macOS':/Linux/.test(ua)?'Linux':'Device';return `${browser} on ${os}`}
function createSession(userId,req={headers:{}}){const token=crypto.randomBytes(32).toString('hex'),csrf=crypto.randomBytes(24).toString('hex'),ua=safe(req.headers?.['user-agent'],500),ip=safe(clientIp(req),100),t=now();db.prepare('INSERT INTO sessions(token,user_id,csrf_token,expires_at,created_at,user_agent,ip_address,device_name,last_seen_at) VALUES(?,?,?,?,?,?,?,?,?)').run(token,userId,csrf,new Date(Date.now()+14*86400000).toISOString(),t,ua,ip,deviceName(ua),t);return {token,csrf}}
function sessionFor(req){const token=parseCookies(req).fs_session;if(!token)return null;const row=db.prepare(`SELECT s.token,s.csrf_token,s.expires_at,s.device_name,s.last_seen_at session_last_seen,u.id,u.name,u.username,u.email,u.role,u.bio,u.avatar_url,u.onboarding_complete,u.email_verified_at,u.profile_public,u.two_factor_enabled,u.created_at FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND s.expires_at>?`).get(token,now())||null;if(row&&(!row.session_last_seen||Date.now()-new Date(row.session_last_seen).getTime()>60000)){const t=now();try{db.prepare('UPDATE sessions SET last_seen_at=? WHERE token=?').run(t,token);db.prepare('UPDATE users SET last_seen_at=? WHERE id=?').run(t,row.id)}catch{}}return row}
function requireUser(req,res,roles){const u=sessionFor(req);if(!u){fail(res,401,'Please sign in to continue.','AUTH_REQUIRED');return null}if(roles&&!roles.includes(u.role)){fail(res,403,'You do not have permission to access this area.','FORBIDDEN');return null}return u}
function requireVerified(user,res){if(user?.role==='admin'||user?.email_verified_at||process.env.NODE_ENV==='test'||process.env.FOODSNAP_REQUIRE_VERIFIED_SOCIAL==='0')return true;fail(res,403,'Verify your email before posting, messaging or uploading community content.','EMAIL_VERIFICATION_REQUIRED');return false}
const B32='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
function b32enc(buf){let bits=0,val=0,out='';for(const b of buf){val=(val<<8)|b;bits+=8;while(bits>=5){out+=B32[(val>>>(bits-5))&31];bits-=5}}if(bits>0)out+=B32[(val<<(5-bits))&31];return out}
function b32dec(s){s=String(s||'').toUpperCase().replace(/[^A-Z2-7]/g,'');let bits=0,val=0,out=[];for(const c of s){val=(val<<5)|B32.indexOf(c);bits+=5;if(bits>=8){out.push((val>>>(bits-8))&255);bits-=8}}return Buffer.from(out)}
function totp(secret,at=Date.now()){const key=b32dec(secret),counter=Math.floor(at/30000),buf=Buffer.alloc(8);buf.writeBigUInt64BE(BigInt(counter));const h=crypto.createHmac('sha1',key).update(buf).digest(),off=h[h.length-1]&15,num=(h.readUInt32BE(off)&0x7fffffff)%1000000;return String(num).padStart(6,'0')}
function verifyTotp(secret,code){code=String(code||'').replace(/\s/g,'');return /^\d{6}$/.test(code)&&[-1,0,1].some(n=>totp(secret,Date.now()+n*30000)===code)}
function requireCsrf(req,res,session){if(['GET','HEAD','OPTIONS'].includes(req.method))return true;const token=String(req.headers['x-csrf-token']||''),expected=String(session?.csrf_token||'');if(!session||!token||token.length!==expected.length||!crypto.timingSafeEqual(Buffer.from(token),Buffer.from(expected))){fail(res,403,'Your session could not be verified. Refresh the page and try again.','CSRF');return false}return true}
function pref(uid){const r=db.prepare('SELECT * FROM preferences WHERE user_id=?').get(uid);return r?{...r,dietary:j(r.dietary_json),cuisines:j(r.cuisines_json),allergens:j(r.allergens_json)}:null}
function activity(uid,type,label,link='',meta={}){db.prepare('INSERT INTO activity_events(user_id,type,label,link,meta_json,created_at) VALUES(?,?,?,?,?,?)').run(uid,type,label,link,JSON.stringify(meta),now())}
function emitUser(uid,type,data={}){uid=Number(uid);const t=now();let eventId=null;try{eventId=Number(db.prepare('INSERT INTO realtime_events(user_id,event_type,payload_json,created_at) VALUES(?,?,?,?)').run(uid,type,JSON.stringify(data),t).lastInsertRowid)}catch{}const set=liveClients.get(uid);if(set?.size){const payload=`id: ${eventId||''}\nevent: ${type}\ndata: ${JSON.stringify(data)}\n\n`;for(const res of [...set]){try{res.write(payload);res._fsLastEventId=eventId||res._fsLastEventId}catch{set.delete(res)}}if(!set.size)liveClients.delete(uid)}return eventId}
function activeUserIds(){try{return db.prepare('SELECT DISTINCT user_id FROM sessions WHERE expires_at>?').all(now()).map(x=>Number(x.user_id)).filter(Boolean)}catch{return []}}
function emitActive(type,data={}){for(const uid of activeUserIds())emitUser(uid,type,data)}
function mutationDomain(pathname=''){const p=String(pathname);if(/^\/api\/(posts|post-comments|engagement|comments|reports)/.test(p))return 'community';if(/^\/api\/(conversations|messages|message)/.test(p))return 'messages';if(/^\/api\/(scans|share)/.test(p))return 'scans';if(/^\/api\/(meal-plans|meal-plan-entries|shopping-lists|shopping-list-items|pantry|households)/.test(p))return 'planning';if(/^\/api\/(user-recipes|collections|profile|users\/[^/]+\/follow|users\/[^/]+\/block)/.test(p))return 'search';if(/^\/api\/(account|settings|reminders|push)/.test(p))return 'account';if(/^\/api\/admin/.test(p))return 'admin';return 'account'}
function mutationEntity(meta,data){const p=String(meta?.path||'');let m=p.match(/^\/api\/posts\/(\d+)/);if(m)return {entityType:'post',entityId:Number(m[1])};m=p.match(/^\/api\/post-comments\/(\d+)/);if(m){const row=db.prepare('SELECT post_id FROM post_comments WHERE id=?').get(Number(m[1]));return {entityType:'post',entityId:Number(row?.post_id||0),commentId:Number(m[1])}};m=p.match(/^\/api\/scans\/(\d+)/);if(m)return {entityType:'scan',entityId:Number(m[1])};m=p.match(/^\/api\/user-recipes\/(\d+)/);if(m)return {entityType:'user_recipe',entityId:Number(m[1])};m=p.match(/^\/api\/collections\/(\d+)/);if(m)return {entityType:'collection',entityId:Number(m[1])};if(p==='/api/posts'&&data?.id)return {entityType:'post',entityId:Number(data.id)};if(p==='/api/user-recipes'&&data?.id)return {entityType:'user_recipe',entityId:Number(data.id)};return {}}
function emitMutationSync(meta,data,status=200){if(!meta?.userId)return;const domain=mutationDomain(meta.path),entity=mutationEntity(meta,data),payload={domain,path:meta.path,method:meta.method,status,actorUserId:Number(meta.userId),clientId:meta.clientId||'',at:now(),...entity};const broad=['community','search','planning'].includes(domain);if(broad)emitActive('sync',payload);else emitUser(meta.userId,'sync',payload)}
function realtimeMutation(domain,data={}){const payload={domain:String(domain||'account'),path:`/internal/${String(domain||'account')}`,method:'SYSTEM',actorUserId:Number(data.userId||0)||null,clientId:'',at:now(),...data};if(['community','search','planning','planner','shopping','pantry'].includes(payload.domain))emitActive('sync',payload);else if(payload.actorUserId)emitUser(payload.actorUserId,'sync',payload);return payload}
function notify(uid,type,title,message,link=''){const id=Number(db.prepare('INSERT INTO notifications(user_id,type,title,message,link,created_at) VALUES(?,?,?,?,?,?)').run(uid,type,title,message,link,now()).lastInsertRowid);emitUser(uid,'notification',{id,type,title,message,link});const pp=pref(uid);if(pp?.push_enabled&&process.env.FOODSNAP_PUSH_ENDPOINT)try{jobs.enqueue('push_notification',{userId:uid,notificationId:id,title,message,link})}catch{}return id}
function sendTrackedEmail(uid,eventType,subject,text,html){const u=db.prepare('SELECT id,email,name FROM users WHERE id=?').get(uid);if(!u)return;const t=now();const rowId=Number(db.prepare(`INSERT INTO email_events(user_id,email,event_type,subject,status,transport,created_at) VALUES(?,?,?,?,?,?,?)`).run(uid,u.email,eventType,subject,'queued',transportName(),t).lastInsertRowid);sendMail({to:u.email,subject,text,html}).then(r=>db.prepare('UPDATE email_events SET status=?,transport=?,detail=? WHERE id=?').run(r.delivered?'sent':'local',r.transport||transportName(),r.id||'',rowId)).catch(e=>{db.prepare('UPDATE email_events SET status=?,detail=? WHERE id=?').run('failed',safe(e.message,500),rowId);console.error('mail',e.message)})}
function recordView(uid,type,id,sourcePath=''){if(!uid||!id)return;const t=now();db.prepare(`INSERT INTO recent_views(user_id,item_type,item_id,source_path,created_at) VALUES(?,?,?,?,?) ON CONFLICT(user_id,item_type,item_id) DO UPDATE SET source_path=excluded.source_path,created_at=excluded.created_at`).run(uid,type,id,safe(sourcePath,240),t);try{const label=itemLabel(type,id)||type;let trail=db.prepare(`SELECT * FROM discovery_trails WHERE user_id=? AND updated_at>? ORDER BY updated_at DESC LIMIT 1`).get(uid,new Date(Date.now()-45*60000).toISOString());if(!trail){const tid=Number(db.prepare('INSERT INTO discovery_trails(user_id,title,path_json,created_at,updated_at) VALUES(?,?,?,?,?)').run(uid,label,JSON.stringify([{type,id,label,href:safe(sourcePath,240),at:t}]),t,t).lastInsertRowid);return tid}const pathItems=j(trail.path_json,[]);const last=pathItems[pathItems.length-1];if(!last||last.type!==type||Number(last.id)!==Number(id)){pathItems.push({type,id,label,href:safe(sourcePath,240),at:t});db.prepare('UPDATE discovery_trails SET path_json=?,updated_at=? WHERE id=?').run(JSON.stringify(pathItems.slice(-18)),t,trail.id)}else db.prepare('UPDATE discovery_trails SET updated_at=? WHERE id=?').run(t,trail.id)}catch(e){console.error('trail',e.message)}}
function itemLabel(type,id){if(type==='food')return db.prepare('SELECT name label FROM foods WHERE id=?').get(id)?.label;if(type==='recipe')return db.prepare('SELECT title label FROM recipes WHERE id=?').get(id)?.label;if(type==='ingredient')return db.prepare('SELECT name label FROM ingredients WHERE id=?').get(id)?.label;if(type==='scan')return db.prepare('SELECT title label FROM scans WHERE id=?').get(id)?.label;return ''}
function itemLink(type,id){if(type==='food')return `/app/foods/${id}`;if(type==='recipe')return `/app/recipes/${id}`;if(type==='ingredient')return `/app/ingredients/${id}`;if(type==='scan')return `/app/scans/${id}`;return '/app'}
function itemLinkForUser(type,id,userId){if(type!=='scan')return itemLink(type,id);const scan=db.prepare('SELECT user_id FROM scans WHERE id=?').get(id);if(scan?.user_id===userId)return `/app/scans/${id}`;const share=db.prepare(`SELECT token FROM share_links WHERE item_type='scan' AND item_id=? AND revoked_at IS NULL AND (expires_at IS NULL OR expires_at>?) ORDER BY created_at DESC LIMIT 1`).get(id,now());return share?`/share/${share.token}`:'/app/community'}
function scanShared(id){return !!db.prepare(`SELECT 1 FROM share_links WHERE item_type='scan' AND item_id=? AND revoked_at IS NULL AND (expires_at IS NULL OR expires_at>?) LIMIT 1`).get(id,now())}
function isBlocked(a,b){if(!a||!b||a===b)return false;return !!db.prepare('SELECT 1 FROM blocks WHERE (blocker_id=? AND blocked_id=?) OR (blocker_id=? AND blocked_id=?)').get(a,b,b,a)}
function notifyPref(uid,key){const p=pref(uid);return !p||p[key]!==0}
function audit(actor,action,entityType,entityId='',metadata={}){try{db.prepare('INSERT INTO audit_logs(actor_user_id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(actor?.id||actor||null,action,entityType,String(entityId||''),JSON.stringify(metadata||{}),now())}catch(e){console.error('audit',e.message)}}
function householdRole(householdId,userId){return db.prepare('SELECT hm.role,h.* FROM household_members hm JOIN households h ON h.id=hm.household_id WHERE hm.household_id=? AND hm.user_id=?').get(Number(householdId),Number(userId))||null}
function canHousehold(householdId,userId,write=false){const r=householdRole(householdId,userId);if(!r)return null;if(write&&!['owner','admin','member'].includes(r.role))return null;return r}
function planAccess(planId,userId){return db.prepare(`SELECT mp.* FROM meal_plans mp WHERE mp.id=? AND (mp.user_id=? OR (mp.household_id IS NOT NULL AND EXISTS(SELECT 1 FROM household_members hm WHERE hm.household_id=mp.household_id AND hm.user_id=?)))`).get(Number(planId),userId,userId)||null}
function shoppingAccess(listId,userId){return db.prepare(`SELECT sl.* FROM shopping_lists sl WHERE sl.id=? AND (sl.user_id=? OR (sl.household_id IS NOT NULL AND EXISTS(SELECT 1 FROM household_members hm WHERE hm.household_id=sl.household_id AND hm.user_id=?)))`).get(Number(listId),userId,userId)||null}
function shoppingActivity(listId,userId,action,itemName='',meta={}){try{db.prepare('INSERT INTO shopping_activity(shopping_list_id,user_id,action,item_name,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(Number(listId),Number(userId)||null,safe(action,40),safe(itemName,120),JSON.stringify(meta||{}),now())}catch{}}
function pantryScope(userId,householdId=null){if(householdId&&canHousehold(householdId,userId))return {householdId:Number(householdId),userId:null};return {householdId:null,userId:Number(userId)}}

function refreshSmartCollection(collectionId,userId){const c=db.prepare('SELECT * FROM collections WHERE id=? AND user_id=? AND is_smart=1').get(collectionId,userId);if(!c)return 0;const rule=j(c.rule_json,{}),where=[],args=[];if(rule.cuisineId){where.push('f.cuisine_id=?');args.push(Number(rule.cuisineId))}if(rule.category){where.push('f.category=?');args.push(safe(rule.category,80))}if(rule.saved){where.push("EXISTS(SELECT 1 FROM saved_items s WHERE s.user_id=? AND s.item_type='food' AND s.item_id=f.id)");args.push(userId)}const rows=db.prepare(`SELECT f.id FROM foods f ${where.length?'WHERE '+where.join(' AND '):''} ORDER BY f.name LIMIT 200`).all(...args);db.prepare("DELETE FROM collection_items WHERE collection_id=? AND item_type='food'").run(c.id);const ins=db.prepare("INSERT OR IGNORE INTO collection_items(collection_id,item_type,item_id,position,created_at) VALUES(?,'food',?,?,?)");rows.forEach((r,i)=>ins.run(c.id,r.id,i,now()));db.prepare('UPDATE collections SET updated_at=? WHERE id=?').run(now(),c.id);return rows.length}
function collectionAccess(collectionId,userId,write=false){const c=db.prepare('SELECT * FROM collections WHERE id=?').get(collectionId);if(!c)return null;if(c.user_id===userId)return {...c,access:'owner'};const col=db.prepare('SELECT role FROM collection_collaborators WHERE collection_id=? AND user_id=?').get(collectionId,userId);if(!col)return null;if(write&&col.role!=='editor')return null;return {...c,access:col.role}}
function issueVerification(userId){const u=db.prepare('SELECT id,email,name,email_verified_at FROM users WHERE id=?').get(userId);if(!u||u.email_verified_at)return null;db.prepare('DELETE FROM email_verification_tokens WHERE user_id=?').run(userId);const token=crypto.randomBytes(32).toString('hex'),hash=crypto.createHash('sha256').update(token).digest('hex'),t=now();db.prepare('INSERT INTO email_verification_tokens(token_hash,user_id,expires_at,created_at) VALUES(?,?,?,?)').run(hash,userId,new Date(Date.now()+24*3600000).toISOString(),t);const link=`${ORIGIN}/auth/verify-email?token=${encodeURIComponent(token)}`;sendTrackedEmail(userId,'email_verification','Verify your FoodSnap email',`Hello ${u.name},\n\nVerify your email: ${link}\n\nThis link expires in 24 hours.`,`<p>Hello ${String(u.name).replace(/[<>&]/g,'')},</p><p><a href="${link}">Verify your FoodSnap email</a></p><p>This link expires in 24 hours.</p>`);return link}
function usageCount(uid){if(!uid)return 0;const day=new Date().toISOString().slice(0,10);return db.prepare(`SELECT COALESCE(SUM(estimated_units),0) n FROM ai_usage WHERE user_id=? AND substr(created_at,1,10)=? AND status IN('success','started')`).get(uid,day)?.n||0}
function usageLimit(uid){const u=uid?db.prepare('SELECT role FROM users WHERE id=?').get(uid):null;if(u?.role==='admin')return Infinity;return Math.max(1,Number(process.env.FOODSNAP_DAILY_AI_LIMIT||40))}
function logUsage({userId=null,scanId=null,feature,provider='',model='',status,latency=0,errorCode='',units=1}){db.prepare('INSERT INTO ai_usage(user_id,scan_id,feature,provider,model,status,latency_ms,error_code,estimated_units,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)').run(userId,scanId,feature,provider,model,status,Math.max(0,Math.round(latency)),safe(errorCode,100),Math.max(1,Math.round(units||1)),now())}
function engagementExists(type,id,userId){if(type==='food')return !!db.prepare('SELECT 1 FROM foods WHERE id=?').get(id);if(type==='recipe')return !!db.prepare('SELECT 1 FROM recipes WHERE id=?').get(id);if(type==='ingredient')return !!db.prepare('SELECT 1 FROM ingredients WHERE id=?').get(id);if(type==='scan'){const row=db.prepare('SELECT user_id FROM scans WHERE id=?').get(id);return !!row&&(row.user_id===userId||scanShared(id))}return false}
function communityActivity(userId){const decorate=(row,kind,direction)=>{const label=itemLabel(row.item_type,row.item_id);if(!label)return null;return {event_id:row.comment_id||null,kind,direction,item_type:row.item_type,item_id:row.item_id,label,body:row.body||'',actor_name:row.actor_name||'',actor_username:row.actor_username||'',created_at:row.created_at,link:itemLinkForUser(row.item_type,row.item_id,userId)}};const mineLikes=db.prepare(`SELECT item_type,item_id,created_at FROM item_likes WHERE user_id=? ORDER BY created_at DESC LIMIT 150`).all(userId).map(x=>decorate(x,'like','given')).filter(Boolean),mineComments=db.prepare(`SELECT id comment_id,item_type,item_id,body,created_at FROM comments WHERE user_id=? AND deleted_at IS NULL ORDER BY created_at DESC LIMIT 150`).all(userId).map(x=>decorate(x,'comment','given')).filter(Boolean),receivedLikes=db.prepare(`SELECT l.item_type,l.item_id,l.created_at,u.name actor_name,u.username actor_username FROM item_likes l JOIN users u ON u.id=l.user_id JOIN scans s ON s.id=l.item_id WHERE l.item_type='scan' AND s.user_id=? AND l.user_id<>? ORDER BY l.created_at DESC LIMIT 150`).all(userId,userId).map(x=>decorate(x,'received_like','received')).filter(Boolean),receivedComments=db.prepare(`SELECT c.id comment_id,c.item_type,c.item_id,c.body,c.created_at,u.name actor_name,u.username actor_username FROM comments c JOIN users u ON u.id=c.user_id JOIN scans s ON s.id=c.item_id WHERE c.item_type='scan' AND s.user_id=? AND c.user_id<>? AND c.deleted_at IS NULL ORDER BY c.created_at DESC LIMIT 150`).all(userId,userId).map(x=>decorate(x,'received_comment','received')).filter(Boolean),mine=[...mineLikes,...mineComments].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)),received=[...receivedLikes,...receivedComments].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)),timeline=[...mine,...received].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));return {summary:{likesGiven:mineLikes.length,commentsWritten:mineComments.length,likesReceived:receivedLikes.length,commentsReceived:receivedComments.length},mine,received,timeline}}

function engagementView(type,id,userId){const likes=db.prepare('SELECT COUNT(*) c FROM item_likes WHERE item_type=? AND item_id=?').get(type,id).c,liked=!!db.prepare('SELECT 1 FROM item_likes WHERE user_id=? AND item_type=? AND item_id=?').get(userId,type,id),comments=db.prepare(`SELECT c.id,c.user_id,c.parent_id,c.body,c.deleted_at,c.created_at,c.updated_at,u.name,u.username,u.avatar_url FROM comments c JOIN users u ON u.id=c.user_id WHERE c.item_type=? AND c.item_id=? AND NOT EXISTS(SELECT 1 FROM blocks b WHERE (b.blocker_id=? AND b.blocked_id=c.user_id) OR (b.blocker_id=c.user_id AND b.blocked_id=?)) ORDER BY c.created_at ASC LIMIT 160`).all(type,id,userId,userId).map(c=>({...c,body:c.deleted_at?'Comment removed':c.body,deleted:!!c.deleted_at}));return {likes,liked,comments}}
function parseRecipe(r){return r?{...r,ingredients:j(r.ingredients_json),steps:j(r.steps_json),tags:j(r.tags_json)}:null}
function parseFood(r){return r?{...r,tags:j(r.tags_json)}:null}
function parseIngredient(r){return r?{...r,tags:j(r.tags_json)}:null}
function parseUserRecipe(r){return r?{...r,ingredients:j(r.ingredients_json),steps:j(r.steps_json),tags:j(r.tags_json)}:null}
function saveCommunityBuffer(buf,mime,name='food-media'){mime=String(mime||'').toLowerCase();const isVideo=mime==='video/mp4'||mime==='video/webm',isImage=['image/jpeg','image/jpg','image/png','image/webp','image/gif'].includes(mime);if(!isVideo&&!isImage)throw Object.assign(new Error('Choose a JPG, PNG, WEBP, GIF, MP4 or WEBM file.'),{status:415});const limit=isVideo?20*1024*1024:8*1024*1024;if(buf.length>limit)throw Object.assign(new Error(isVideo?'Videos must be 20MB or smaller.':'Images must be 8MB or smaller.'),{status:413});if(isImage)mime=inspectImage(buf,mime);if(isVideo){if(mime==='video/mp4'&&buf.subarray(4,12).toString('ascii').indexOf('ftyp')<0)throw Object.assign(new Error('That MP4 file is not valid.'),{status:415});if(mime==='video/webm'&&!(buf[0]===0x1a&&buf[1]===0x45&&buf[2]===0xdf&&buf[3]===0xa3))throw Object.assign(new Error('That WEBM file is not valid.'),{status:415})}const ext=mime==='image/jpeg'?'jpg':mime.split('/')[1],filename=`community-${Date.now()}-${crypto.randomBytes(10).toString('hex')}.${ext}`;fs.writeFileSync(path.join(uploadsDir,filename),buf);return {url:`/api/community-media/${filename}`,mime,name:safe(name,180),bytes:buf.length,type:isVideo?'video':'image'}}
