function userRecipeView(r,viewerId=null){if(!r)return null;const out=parseUserRecipe(r);out.author=db.prepare('SELECT id,name,username,avatar_url FROM users WHERE id=?').get(r.user_id);out.media=db.prepare('SELECT * FROM recipe_media WHERE user_recipe_id=? ORDER BY position,id').all(r.id);out.rating=db.prepare(`SELECT ROUND(AVG(rating),1) avg_rating,COUNT(*) rating_count,SUM(made_it) made_count FROM recipe_ratings WHERE recipe_type='user' AND recipe_id=?`).get(r.id);out.my_rating=viewerId?db.prepare("SELECT * FROM recipe_ratings WHERE user_id=? AND recipe_type='user' AND recipe_id=?").get(viewerId,r.id)||null:null;out.save_count=db.prepare('SELECT COUNT(*) c FROM user_recipe_saves WHERE user_recipe_id=?').get(r.id).c;out.saved=viewerId?!!db.prepare('SELECT 1 FROM user_recipe_saves WHERE user_id=? AND user_recipe_id=?').get(viewerId,r.id):false;return out}
function canViewUserRecipe(r,u){if(!r)return false;if(u&&r.user_id===u.id)return true;if(r.status!=='published'||!r.published_at)return false;if(r.visibility==='public')return true;if(!u)return false;if(r.visibility==='followers')return !!db.prepare('SELECT 1 FROM follows WHERE follower_id=? AND following_id=?').get(u.id,r.user_id);return false}
