function scheduleJobs(){try{const t=now();if(backups.due()&&!db.prepare("SELECT 1 FROM system_jobs WHERE type='automatic_backup' AND status IN('queued','retrying','running') LIMIT 1").get())jobs.enqueue('automatic_backup',{});for(const r of db.prepare("SELECT id FROM reminders WHERE status='scheduled' AND run_at<=? LIMIT 100").all(t)){jobs.enqueue('reminder',{id:r.id});db.prepare("UPDATE reminders SET status='queued',updated_at=? WHERE id=? AND status='scheduled'").run(t,r.id)}for(const r of db.prepare("SELECT id FROM user_recipes WHERE status='draft' AND scheduled_at IS NOT NULL AND scheduled_at<=? LIMIT 50").all(t)){jobs.enqueue('publish_recipe',{id:r.id});db.prepare('UPDATE user_recipes SET scheduled_at=NULL WHERE id=? AND scheduled_at IS NOT NULL').run(r.id)}for(const r of db.prepare("SELECT id FROM posts WHERE scheduled_at IS NOT NULL AND scheduled_at<=? AND published_at IS NULL LIMIT 50").all(t)){jobs.enqueue('publish_post',{id:r.id});db.prepare('UPDATE posts SET scheduled_at=NULL WHERE id=? AND published_at IS NULL').run(r.id)}for(const r of db.prepare("SELECT id FROM account_deletion_requests WHERE status='scheduled' AND execute_at<=? LIMIT 20").all(t)){jobs.enqueue('account_delete',{id:r.id});db.prepare("UPDATE account_deletion_requests SET status='queued' WHERE id=? AND status='scheduled'").run(r.id)}for(const r of db.prepare("SELECT id,file_name FROM data_exports WHERE expires_at IS NOT NULL AND expires_at<=? AND file_url<>''").all(t)){if(r.file_name)try{fs.rmSync(path.join(exportsDir,path.basename(r.file_name)),{force:true})}catch{}db.prepare("UPDATE data_exports SET file_url='',file_name='',status='expired',updated_at=? WHERE id=?").run(t,r.id)}}catch(e){console.error('scheduler',e.message)}}


