function serveStatic(req,res,url){let pathname=decodeURIComponent(url.pathname);if(pathname.startsWith('/assets/'))return serveFile(res,path.join(publicDir,'assets',pathname.slice(8)),true);const file=path.join(publicDir,pathname==='/'?'index.html':pathname.slice(1));if(fs.existsSync(file)&&fs.statSync(file).isFile())return serveFile(res,file,true);return serveFile(res,path.join(publicDir,'index.html'),false)}
function serveFile(res,file,cache=true){try{const st=fs.statSync(file),ext=path.extname(file).toLowerCase(),mutable=['.html','.js','.css','.webmanifest'].includes(ext)||file.endsWith('service-worker.js');securityHeaders(res);res.writeHead(200,{'Content-Type':MIME[ext]||'application/octet-stream','Content-Length':st.size,'Cache-Control':mutable?'no-store':(cache?'public,max-age=3600':'no-store')});fs.createReadStream(file).pipe(res)}catch{fail(res,404,'Not found.','NOT_FOUND')}}

const server=http.createServer(async(req,res)=>{try{const url=new URL(req.url,ORIGIN);if(url.pathname.startsWith('/api/'))return await api(req,res,url);return serveStatic(req,res,url)}catch(e){console.error(e);if(!res.headersSent)fail(res,e.status||500,e.status?e.message:'Something went wrong. Please try again.','SERVER_ERROR');else res.end()}});
const workerOnly=process.env.FOODSNAP_WORKER_ONLY==='1';
const runBackground=workerOnly||process.env.FOODSNAP_RUN_JOBS==='1'||process.env.NODE_ENV!=='production';
let backgroundTimers=[];
function startBackground(){if(backgroundTimers.length)return;backgroundTimers.push(setInterval(()=>tickWorker().catch(e=>console.error('analysis worker',e.message)),700));backgroundTimers.push(setInterval(cleanup,3600000));backgroundTimers.push(jobs.start(900));backgroundTimers.push(setInterval(scheduleJobs,30000));scheduleJobs();cleanup();return backgroundTimers}
function stopBackground(){for(const t of backgroundTimers){try{clearInterval(t)}catch{}}backgroundTimers=[]}
if(runBackground)startBackground();
if(!workerOnly)server.listen(PORT,()=>console.log(`FoodSnap running at http://localhost:${PORT}`));
module.exports={server,startBackground,stopBackground,scheduleJobs,tickWorker,cleanup,jobs};
